/**
 * Hairlux logo mark, base64-encoded PNG (transparent background) -- the
 * LIGHT/white variant, deliberately chosen over the dark variant since
 * this is used on the ID card's dark background, where the light variant
 * renders crisp and the dark one would show up faint. No static-asset-copy
 * convention exists in this project's build (no nest-cli.json assets
 * config, no assets/ folder), so this is embedded directly as a source
 * constant -- works identically in every deployment environment with zero
 * extra build configuration, at the cost of a larger source file. Source:
 * logo-light.webp, converted to PNG to preserve transparency (pdf-lib can
 * only embed PNG/JPG directly, not webp).
 * Decode with Buffer.from(HAIRLUX_LOGO_BASE64, 'base64') before passing
 * to pdfDoc.embedPng().
 */
export const HAIRLUX_LOGO_BASE64 =
    '';